        tfT: 'A avó vai fazer noventa anos.', tfTEn: 'Grandma is turning ninety.', tfF: 'Quem ligou tem muito dinheiro.', tfFEn: 'The caller has a lot of money.', tfN: 'A avó mora em Molinar.', tfNEn: 'Grandma lives in Molinar.',
